import { GoogleSpreadsheet } from 'google-spreadsheet';
import { JWT } from 'google-auth-library';
import { HTTPError } from 'ky';

const auth = new JWT({
  email: import.meta.env.GOOGLE_SA_EMAIL,           // server-only env
  key: import.meta.env.GOOGLE_SA_PRIVATE_KEY.replace(/\\n/g, '\n'),
  scopes: ['https://www.googleapis.com/auth/spreadsheets'],
});

export const doc = new GoogleSpreadsheet(import.meta.env.SHEET_ID, auth, {
  // constructor option: retryConfig?: RetryOptions | number  (passed to ky `retry`)
  retryConfig: {
    limit: 3,
    methods: ['get', 'put', 'delete', 'post'],
    statusCodes: [408, 413, 429, 500, 502, 503, 504],
    afterStatusCodes: [413, 429, 503],   // use Retry-After when present
    backoffLimit: 10_000,
    shouldRetry: ({ request, error }) =>
      request.method !== 'POST' ||
      (error instanceof HTTPError && [429, 503].includes(error.response.status)),
  },
});

const params = new URLSearchParams();
for (const r of ['Rugs!A1:Z', 'Collections!A1:Z', 'Tags!A1:Z', 'FX!A1:C']) params.append('ranges', r);
params.append('valueRenderOption', 'UNFORMATTED_VALUE');   // numbers as JSON numbers, not "1.234,50"
params.append('dateTimeRenderOption', 'FORMATTED_STRING'); // only honoured when not FORMATTED_VALUE
params.append('majorDimension', 'ROWS');

const res = await doc.sheetsApi.get('values:batchGet', { searchParams: params });
const data = await res.json<{ valueRanges: { range: string; values?: unknown[][] }[] }>();
// data.valueRanges is in the same order as the requested ranges
const [rugs, collections, tags, fx] = data.valueRanges.map((vr) => vr.values ?? []);
// then: header = rugs[0]; rows = rugs.slice(1) -> Zod schema with z.coerce.number()

