const opts = {
  valueRenderOption: 'UNFORMATTED_VALUE',
  dateTimeRenderOption: 'FORMATTED_STRING', // not declared in GetValuesRequestOptions in 5.3.0
} as GetValuesRequestOptions & { dateTimeRenderOption: 'FORMATTED_STRING' };

// GET values/Rugs!A1:Z?valueRenderOption=...&dateTimeRenderOption=...
const values: unknown[][] = await sheet.getCellsInRange('A1:Z', opts);
// or several ranges in one request: GET values:batchGet?ranges=Rugs!A1:Z&ranges=Rugs!AA1:AB&valueRenderOption=...
const [a, b] = await sheet.batchGetCellsInRange(['A1:Z', 'AA1:AB'], opts);

