import { JWT } from 'google-auth-library';

const client = new JWT({ email, key, scopes: ['https://www.googleapis.com/auth/spreadsheets'] });

const res = await client.request<{ valueRanges: { values?: unknown[][] }[] }>({
  url: `https://sheets.googleapis.com/v4/spreadsheets/${SHEET_ID}/values:batchGet`,
  params: {
    ranges: ['Rugs!A1:Z', 'FX!A1:C'],
    valueRenderOption: 'UNFORMATTED_VALUE',
    dateTimeRenderOption: 'FORMATTED_STRING',
  },
  retry: true,                       // gaxios: no retries at all unless retry/retryConfig is set
  retryConfig: {                     // defaults when enabled: retry 3, GET/HEAD/PUT/OPTIONS/DELETE,
    retry: 3,                        // statusCodesToRetry [[100,199],[408,408],[429,429],[500,599]]
    retryDelay: 500,
    maxRetryDelay: 10_000,
    statusCodesToRetry: [[429, 429], [500, 599]],
  },
});
const [rugs, fx] = res.data.valueRanges.map((vr) => vr.values ?? []);

import { sheets } from '@googleapis/sheets';
import { JWT } from 'google-auth-library';

const api = sheets({ version: 'v4', auth: new JWT({ email, key, scopes: ['https://www.googleapis.com/auth/spreadsheets'] }) });
const { data } = await api.spreadsheets.values.batchGet(
  {
    spreadsheetId: SHEET_ID,
    ranges: ['Rugs!A1:Z', 'FX!A1:C'],
    valueRenderOption: 'UNFORMATTED_VALUE',     // Params$Resource$Spreadsheets$Values$Batchget
    dateTimeRenderOption: 'FORMATTED_STRING',
  },
  { retryConfig: { retry: 3, statusCodesToRetry: [[429, 429], [500, 599]] } } // MethodOptions extends GaxiosOptions
);
